// 1) Declaration — a statement, registered before any line runs
function formatName(name) {
  return name.trim().toLowerCase();
}

// 2) Function expression — a value, stored in a binding
const shout = function (text) {
  return text.toUpperCase() + '!';
};

// 3) Arrow expression — also a value; lightest syntax, no this of its own
const whisper = (text) => text.toLowerCase() + '...';

console.log(formatName('  MAYA ')); // "maya"
console.log(shout('hello'));        // "HELLO!"
console.log(whisper('HI'));         // "hi..."

console.log(plan('standup')); // "agenda: standup" — the WHOLE function moved up
function plan(meeting) {
  return 'agenda: ' + meeting;
}

try {
  announce('retro'); // the var NAME exists (hoisted, holding undefined) — the function does not
  var announce = function (meeting) { return 'notes: ' + meeting; };
} catch (e) {
  console.log(e.name); // "TypeError" — you called undefined
}

try {
  notify('demo'); // the binding is in the temporal dead zone until its own line
  const notify = (meeting) => 'notes: ' + meeting;
} catch (e) {
  console.log(e.name); // "ReferenceError" — dead zone, not "undefined"
}

function report() {
  return this; // a regular function's this depends on HOW it is called, not where it is written
}

const server = { name: 'prod', report };

console.log(server.report().name);                  // "prod" — obj.method(): this = obj
console.log(report.call({ name: 'staging' }).name); // "staging" — call/apply/bind set it explicitly
console.log(report() === undefined);                // true — a plain call in strict mode (this
                                                    // playground's mode) hands you undefined

const counter = {
  hits: 0,
  startBroken() {
    setTimeout(function () {
      // the HOST invokes callbacks with ITS choice of this (the global object
      // in browsers) — never the object this function was written inside:
      this.hits += 1;
      console.log('broken: this.hits =', this.hits, '· counter.hits =', counter.hits);
    }, 0);
  },
  startFixed() {
    setTimeout(() => {
      // the arrow has no this of its own → it uses startFixed's this,
      // and the call counter.startFixed() set that to counter:
      this.hits += 1;
      console.log('fixed: counter.hits =', this.hits);
    }, 0);
  },
};

counter.startBroken();
counter.startFixed();
console.log('both callbacks scheduled'); // synchronous — prints FIRST

const widget = {
  label: 'widget',
  build() {
    // inside build, this === widget (it was called as widget.build())
    const ui = {
      label: 'ui-card',
      print() {
        return 'regular method sees: ' + this.label; // called as ui.print() → this = ui
      },
      printArrow: () => 'arrow method sees: ' + this.label, // no own this → build's this!
    };
    return ui.print() + ' / ' + ui.printArrow();
  },
};

console.log(widget.build());
// "regular method sees: ui-card / arrow method sees: widget"

// Defaults fire ONLY for undefined — null is a deliberate value and passes through:
function greet(name = 'guest', greeting = 'hello') {
  return `${greeting}, ${name}`;
}
console.log(greet());                     // "hello, guest" — both defaults fired
console.log(greet('Ada'));                // "hello, Ada"
console.log(greet(null));                 // "hello, null" — null did NOT fire the default
console.log(greet(undefined, 'welcome')); // "welcome, guest"

// Rest: everything after the named parameters arrives as a REAL array:
function summarize(prefix, ...skills) {
  return `${prefix}: ${skills.length} — ${skills.map((s) => s.toUpperCase()).join(', ')}`;
}
console.log(summarize('stack', 'ts', 'js', 'sql')); // "stack: 3 — TS, JS, SQL"

function legacy() {
  console.log(arguments.length);          // 2
  console.log(typeof arguments.map);      // "undefined" — array-LIKE, not an array
  console.log(Array.isArray(arguments));  // false
  return Array.from(arguments).join('-'); // the classic conversion
}
console.log(legacy('a', 'b')); // "a-b"

// Arrows have NO arguments of their own. Nested inside a regular function,
// the name resolves to the ENCLOSING function's arguments object:
function outer() {
  const inner = () => arguments[0] + ' (borrowed from outer)';
  return inner();
}
console.log(outer('shared')); // "shared (borrowed from outer)"

// Named function expression: the inner name is visible ONLY inside the function
const countdown = function tick(n) {
  if (n === 0) return 'liftoff';
  return tick(n - 1); // recursion that does not depend on the outer binding
};
console.log(countdown(3)); // "liftoff"
console.log(typeof tick);  // "undefined" — the name never leaked (Lesson 1's safe probe)

// Arrows have no inner name — they recurse through the VARIABLE, which only
// works once the binding exists at call time:
const factorial = (n) => (n <= 1 ? 1 : n * factorial(n - 1));
console.log(factorial(5)); // 120

