// 1. Jae wins the dispute — kept as evidence, the failed early call:
try {
  earlyLog('too soon'); // the binding below is still in its dead zone here
  const earlyLog = (source) => 'boot from ' + source;
} catch (e) {
  console.log(e.name); // "ReferenceError"
}

// 2. The modern form: binding first, call after — order is now load-bearing
const logBoot = (source) => console.log('boot from ' + source);
logBoot('playground'); // "boot from playground"

// 3. The 2013 self-trap, retired: the arrow has no this of its own,
//    so it uses renderLater's this — which the call site sets to badge
const badge = {
  text: 'DEPLOY',
  renderLater() {
    setTimeout(() => {
      console.log('button: ' + this.text);
    }, 0);
  },
};
badge.renderLater(); // "button: DEPLOY"

